if (input.body) {
  const body = JSON.parse(input.body);
  const recipientArray = body.recipientFormData || [];
  const formArray = body.formData || [];

  // Convert to lowercase key-value map
  const formdata = formArray.reduce((acc, field) => {
    if (field.name && field.value !== undefined) {
      acc[field.name.toLowerCase()] = field.value;
    }
    return acc;
  }, {});

  // Recipients (exclude @masonllc.net)
  const recipients = recipientArray
    .filter(r => !(r.email || "").toLowerCase().includes("@masonllc.net"))
    .map(r => {
      const name = r.name || "";
      const [first, ...lastParts] = name.trim().split(" ");
      return {
        name,
        first,
        last: lastParts.join(" ").trim(),
        email: r.email || ""
      };
    });

  // Helper to parse name into first/last
  const parseName = (name = "") => {
    const [first, ...lastParts] = name.trim().split(" ");
    return {
      full: name,
      first,
      last: lastParts.join(" ").trim()
    };
  };

  // Build Trusted Contacts Array (support both patterns)
  const trustedContacts = [];

  // Generic / fallback contact
  if (formdata["trusted contact full name"]) {
    const parsed = parseName(formdata["trusted contact full name"]);
    trustedContacts.push({
      tcname: parsed.full,
      tcfirst: parsed.first,
      tclast: parsed.last,
      relationship: formdata["trusted contact relationship to client"] || "",
      address: formdata["trusted contact address"] || "",
      city: formdata["trusted contact city"] || "",
      state: formdata["trusted contact state"] || "",
      zip: formdata["trusted contact zip"] || "",
      phone: formdata["trusted contact phone number"] || "",
      tcemail: formdata["trusted contact email"] || ""
    });
  }

  // Numbered contacts
  [1, 2].forEach(i => {
    const nameKey = `trusted contact ${i} name`;
    if (formdata[nameKey]) {
      const parsed = parseName(formdata[nameKey]);
      trustedContacts.push({
        tcname: parsed.full,
        tcfirst: parsed.first,
        tclast: parsed.last,
        relationship: formdata[`trusted contact ${i} relationship`] || "",
        address: [
          formdata[`trusted contact ${i} street 1`] || "",
          formdata[`trusted contact ${i} street 2`] || ""
        ].filter(Boolean).join(", "),
        city: formdata[`trusted contact ${i} city`] || "",
        state: formdata[`trusted contact ${i} state`] || "",
        zip: formdata[`trusted contact ${i} zip`] || "",
        phone: formdata[`trusted contact ${i} phone`] || "",
        tcemail: formdata[`trusted contact ${i} email`] || ""
      });
    }
  });

  return {
    recipients,
    trustedContacts,
    body
  };
} else {
  return {
    error: "Missing input.body"
  };
}

