First, search for household by email address. If found, return the record. If not found, search by last name. If found, return the record, otherwise, create a new household using name and email from inputs.

Inputs: auth, addEmail, first, last, email, role, cofirst, colast, coemail, corole, householdName, householdEmail

Code: /**
 * Cleaned Wealthbox Contact/Household Manager with Detailed Logging
 */
const { auth, runpart = "all", findcreate } = inputData;
const baseUrl = "https://api.crmworkspace.com/v1";
const logs = [];

// 1. Unified Input Fetcher
const get = (keys, def = "") => {
  for (const k of keys) if (inputData[k]) return String(inputData[k]).trim();
  return def;
};

// Logic for Create vs Find-Only
const canCreate = (val, globalDefault) => {
  const s = String(val || globalDefault || "true").toLowerCase();
  return !["false", "0", "find", "no"].includes(s);
};

const state = {
  hh: {
    name: get(["householdName", "household_name", "household"]),
    email: get(["householdEmail", "household_email"]),
    fc: canCreate(inputData.hh_findcreate, findcreate)
  },
  p1: {
    first: get(["first", "first_name"]),
    last: get(["last", "last_name"]),
    email: get(["email", "contactEmail"]),
    role: get(["role", "primaryRole"], "Head"),
    fc: canCreate(inputData.primary_findcreate, findcreate)
  },
  p2: {
    first: get(["cofirst", "co_first"]),
    last: get(["colast", "co_last"]),
    email: get(["coemail", "co_email"]),
    role: get(["corole", "co_role"], "Spouse"),
    fc: canCreate(inputData.co_findcreate, findcreate)
  }
};

// 2. API Helper
async function api(path, method = "GET", body = null) {
  const res = await fetch(`${baseUrl}/${path}`, {
    method,
    headers: { "Content-Type": "application/json", "ACCESS_TOKEN": auth },
    body: body ? JSON.stringify(body) : null
  });
  const data = await res.json().catch(() => ({}));
  return { ok: res.ok, status: res.status, data };
}

// 3. Search & Create Engine
async function processEntity(type, config) {
  const { first, last, name, email, fc } = config;
  const identifier = name || `${first} ${last}`.trim();

  logs.push(`🔍 Checking for ${type}: "${identifier}"...`);

  let found = null;

  // A. Email Search
  if (email) {
    const { data } = await api(`contacts?type=${type}&email=${encodeURIComponent(email)}`);
    found = (data.contacts || [])[0];
    if (found) logs.push(`   ✅ Match found by email: ${email}`);
  }

  // B. Name Search (if email failed)
  if (!found && (last || name)) {
    const searchVal = name || last;
    const { data } = await api(`contacts?type=${type}&name=${encodeURIComponent(searchVal)}`);
    const results = data.contacts || [];

    // For Persons, refine by first name if possible
    found = (type === "Person" && first) 
      ? results.find(c => c.first_name?.toLowerCase() === first.toLowerCase()) 
      : results[0];

    if (found) logs.push(`   ✅ Match found by name: ${found.name || found.first_name}`);
  }

  if (found) return found;

  // C. Create Logic
  if (fc && identifier) {
    logs.push(`   ✨ No match. Creating new ${type}...`);
    const payload = type === "Household" 
      ? { type, name: identifier }
      : { type: "Person", first_name: first, last_name: last, emails: [{ address: email, kind: "Personal", principal: true }] };

    const { ok, data } = await api("contacts", "POST", payload);
    if (ok) {
      logs.push(`   🚀 Created ${type} (ID: ${data.id})`);
      return data;
    }
    logs.push(`   ❌ Create failed for ${type}. Check inputs.`);
  } else {
    logs.push(`   ⚠️ No match found and "Create" is disabled.`);
  }

  return null;
}

// 4. Linking Engine
async function linkMember(hhId, contactId, role) {
  if (!hhId || !contactId) return;
  const { ok } = await api(`households/${hhId}/members`, "POST", { id: Number(contactId), title: role });
  logs.push(ok ? `🔗 Linked ID ${contactId} to HH ${hhId} as "${role}"` : `❌ Link failed for ID ${contactId}`);
}

// 5. Execution Flow
async function main() {
  const output = { household: null, primary: null, co: null };

  // Run Household Step
  if (["all", "household"].includes(runpart)) {
    output.household = await processEntity("Household", state.hh);
  }

  // Run Contacts Step
  if (["all", "contacts", "all"].includes(runpart)) {
    if (state.p1.last) output.primary = await processEntity("Person", state.p1);
    if (state.p2.last) output.co = await processEntity("Person", state.p2);
  }

  // Run Linking Step
  if (["all", "link"].includes(runpart)) {
    const hhId = output.household?.id || get(["linkHouseholdId", "hhId"]);
    await linkMember(hhId, output.primary?.id, state.p1.role);
    await linkMember(hhId, output.co?.id, state.p2.role);
  }

  return { 
    summary: logs, 
    household_id: output.household?.id,
    primary_id: output.primary?.id,
    co_id: output.co?.id
  };
}

return await main();

