// === HELPERS ===
function getFirstFullWeekStart(month, year) {
  const firstOfMonth = new Date(year, month, 1);
  const day = firstOfMonth.getDay(); // 0=Sun, 1=Mon, ... 6=Sat
  const firstMonday = new Date(firstOfMonth);
  firstMonday.setDate(firstOfMonth.getDate() + ((8 - day) % 7));
  const sunday = new Date(firstMonday);
  sunday.setDate(firstMonday.getDate() + 6);
  if (sunday.getMonth() !== month) {
    firstMonday.setDate(firstMonday.getDate() + 7);
  }
  return firstMonday;
}

function getPreviousBusinessDay(date, weeksEarlier) {
  const target = new Date(date);
  target.setDate(target.getDate() - 7 * weeksEarlier);
  const d = target.getDay();
  if (d === 0) target.setDate(target.getDate() + 1); // Sunday → Monday
  if (d === 6) target.setDate(target.getDate() + 2); // Saturday → Monday
  return target;
}

function nextWeekday(date) {
  const d = date.getDay();
  if (d === 6) date.setDate(date.getDate() + 2); // Saturday → Monday
  if (d === 0) date.setDate(date.getDate() + 1); // Sunday → Monday
  return date;
}

function fmt(date) {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

// === MAIN LOGIC ===
