const auth = inputData.auth; 
const perPage = 100;
const baseUrl = 'https://api.crmworkspace.com/v1/contacts';
let all = [];
let page = 1;

// --- Helper: fetch JSON ---
function fetchJSON(url) {
  return fetch(url, {
    headers: { 'Content-Type': 'application/json', 'ACCESS_TOKEN': auth }
  }).then(function (r) { return r.json(); });
}

// --- Helper: fetch page ---
function fetchPage(pageNum) {
  const url = baseUrl + '?page=' + pageNum + '&per_page=' + perPage + '&type=person';
  return fetchJSON(url);
}

// --- Helper: determine client & apply filters ---
function isValidTarget(contact) {
  var firstName = (contact.first_name || '').toLowerCase().trim();
  var type = (contact.contact_type || '').toLowerCase();

  // Normalize tags (lowercase, handle smart quotes, trim whitespace)
  var tags = (contact.tags || []).map(function (t) { 
    return (t.name || '').toLowerCase().replace(/[’‘'"`]/g, "'").trim(); 
  });

  // 1. HARD TAG EXCLUSIONS (Ex Prospect or Ex Client)
  if (tags.indexOf('ex prospect') !== -1 || tags.indexOf('ex client') !== -1) return false;

  // 2. GENERAL STATUS EXCLUSIONS (Past Clients)
  if (type.indexOf('past') !== -1 || tags.indexOf('past') !== -1) return false;

  // 3. THE PRIMARY REQUIREMENT: Must contain "Contact Client" tag
  // No name or location filters required anymore.
  return tags.indexOf('contact client') !== -1;
}

// --- Helper: get primary email address ---
function getPrimaryEmail(contact) {
  var emails = contact.email_addresses || [];
  if (!emails.length) return '';
  var primary = emails.find(function (e) { return e.principal === true || e.primary === true; });
  return primary ? primary.address : (emails[0] ? emails[0].address : '');
}

// --- Recursive pagination to fetch every person record ---
function getAllContacts() {
  return fetchPage(page).then(function (res) {
    var items = res.contacts || [];
    for (var i = 0; i < items.length; i++) {
      if (isValidTarget(items[i])) all.push(items[i]);
    }
    if (items.length === perPage) {
      page++;
      return getAllContacts();
    } else {
      return all;
    }
  });
}

// --- MAIN ---
getAllContacts()
  .then(function (contacts) {
    var grouped = {};

    // Group contacts by their Household ID
    for (var i = 0; i < contacts.length; i++) {
      var c = contacts[i];
      var hh = c.household || {};
      if (!hh.id) continue;
      if (!grouped[hh.id]) grouped[hh.id] = { name: hh.name || '', members: [] };
      grouped[hh.id].members.push(c);
    }

    var results = [];
    for (var id in grouped) {
      var g = grouped[id];
      var members = g.members;

      // Identify Head of Household
      var head = members.find(function (m) {
        var r = (m.household && m.household.role) || '';
        return /head/i.test(r);
      }) || members[0] || {};

      // Identify Spouse/Partner
      var spouse = members.find(function (m) {
        var r = (m.household && m.household.role) || '';
        return /spouse|partner|co-?head/i.test(r);
      });

      if (!spouse && members.length > 1) {
        spouse = members.find(function (m) { return m.id !== head.id; });
      }

      var headEmail = getPrimaryEmail(head);
      var spouseEmail = spouse ? getPrimaryEmail(spouse) : '';

      // Consolidate Unique Tags for the Household
      var tagSet = {};
      var allTags = [];
      [head, spouse].forEach(function (p) {
        if (p && p.tags) {
          p.tags.forEach(function (t) {
            if (t && t.name && !tagSet[t.name]) {
              tagSet[t.name] = true;
              allTags.push(t.name);
            }
          });
        }
      });

      // Format the Checklist Name: "Last, First and Last, First"
      var checklistName = (head.last_name || '') + ', ' + (head.first_name || '');
      if (spouse && spouse.first_name) {
        checklistName += ' and ' + (spouse.last_name || '') + ', ' + (spouse.first_name || '');
      }

      results.push({
        household_id: id,
        household_name: g.name,
        Head_Name: (head.first_name || '') + ' ' + (head.last_name || ''),
        Head_First: head.first_name,
        Head_Last: head.last_name,
        Head_Email: headEmail,
        Head_ID: head.id,
        Spouse_Name: spouse ? (spouse.first_name || '') + ' ' + (spouse.last_name || '') : '',
        Spouse_First: spouse? spouse.first_name : '',
        Spouse_Last: spouse? spouse.last_name: '',
        Spouse_ID: spouse? spouse.id : '',
        Spouse_Email: spouseEmail,
        Unique_Tags: allTags.join(', '),
        Checklist_Name: checklistName
      });
    }

    callback(null, { count: results.length, households: results });
  })
  .catch(function (err) {
    callback(err);
