    const url = `${baseUrl}?page=${page}&per_page=${perPage}&order=desc&start_date_min=${dateMin}&start_date_max=${dateMax}`;

    return fetch(url, {
        headers: { 'Content-Type': 'application/json', 'ACCESS_TOKEN': auth }
    })
    .then(r => r.json())
    .then(res => {
        const items = res.events || [];

        // Loop through current page items
        for (let e of items) {
            const keywordFound = getKeywordIfQualified(e);

            // 🛑 STOP AND RETURN immediately upon finding the first match
            if (keywordFound) {
                const templateData = getTemplateData(keywordFound);
                return {
                    id: e.id,
                    title: e.title,
                    starts_at: e.starts_at,
                    description: e.description,
                    matched_keyword: templateData.keyword,
                    template_id: templateData.template_id,
                    linked_to_ids: (e.linked_to || []).map(l => l.id)
                };
            }
        }

        // If no match on this page, check if there are more pages
        if (items.length === perPage && page < 10) {
            page++;
            return findMostRecent();
        }

        return null; // No match found in the history
    });
}

