const startDateStr = inputData.start_date; // e.g. "2025-10-20" or "2025-10-22"
const start = new Date(startDateStr);

// Get day of week (0 = Sunday, 1 = Monday, ... 6 = Saturday)
const day = start.getDay();

// Calculate how many days since Monday
let offset;
if (day === 1) {
  // Already Monday → go back one full week
  offset = 7;
} else if (day === 0) {
  // Sunday → previous Monday was 6 days ago
  offset = 6;
} else {
  // e.g. Wednesday → go back (day - 1) days
  offset = day - 1;
}

// Compute Monday before
const monday = new Date(start);
monday.setDate(start.getDate() - offset);

// Format YYYY-MM-DD
function fmt(date) {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

// === RETURN for Zapier ===
return { monday_before: fmt(monday) };

