const today = new Date();
const twentyFourMonthsAgo = new Date();
twentyFourMonthsAgo.setMonth(today.getMonth() - 24);

const formatDate = (date) => date.toISOString().split('T')[0];
const dateMax = formatDate(today);
const dateMin = formatDate(twentyFourMonthsAgo);

/**
 * Maps the extracted keyword to its specific Template ID
 */
function getTemplateData(text) {
  const t = text.toLowerCase();
  if (t.includes('fall')) return { keyword: 'Fall', template_id: 'l1W0lYhmhvRJ6iuqZv9F3Q' };
  if (t.includes('spring')) return { keyword: 'Spring', template_id: 'loRG91A8pLCNYETt7g9OPg' };
  if (t.includes('plan implementation')) return { keyword: 'Plan Implementation', template_id: 'sMxWZusYz8EHzt2VFkRN-g' };
  return { keyword: 'Unknown', template_id: '' };
}

/**
 * Logic: Matches "Event Name" label + Keywords 
 * AND checks if Household/Head/Spouse IDs are linked.
 */
function getKeywordIfQualified(event) {
    const desc = (event.description || '').toLowerCase();
    const title = (event.title || '').toLowerCase();
    const combined = title + " " + desc;

    // A. KEYWORD CHECK (Requires "event name" prefix)
    let matchedText = null;
    if (combined.includes("event name")) {
        const afterLabel = combined.split("event name")[1];
        const targets = ['fall', 'spring', 'plan implementation', 'plan imeplementation'];

        const found = targets.find(k => afterLabel.includes(k));
        if (found) matchedText = found;
    }

    if (!matchedText) return null;

    // B. LINKED ID CHECK
    const linkedIds = (event.linked_to || []).map(l => String(l.id));
    const hasLinkedMatch = (householdId && linkedIds.includes(householdId)) ||
                           (headId && linkedIds.includes(headId)) ||
                           (spouseId && linkedIds.includes(spouseId));

    return hasLinkedMatch ? matchedText : null;
}

// 2. Optimized Fetcher (Stops at first match)
function findMostRecent() {
    const url = `${baseUrl}?page=${page}&per_page=${perPage}&order=desc&start_date_min=${dateMin}&start_date_max=${dateMax}`;

    return fetch(url, {
        headers: { 'Content-Type': 'application/json', 'ACCESS_TOKEN': auth }
    })
    .then(r => r.json())
    .then(res => {
        const items = res.events || [];

        // Loop through current page items
        for (let e of items) {
            const keywordFound = getKeywordIfQualified(e);

            // 🛑 STOP AND RETURN immediately upon finding the first match
            if (keywordFound) {
                const templateData = getTemplateData(keywordFound);
                return {
                    id: e.id,
                    title: e.title,
                    starts_at: e.starts_at,
                    description: e.description,
                    matched_keyword: templateData.keyword,
                    template_id: templateData.template_id,
                    linked_to_ids: (e.linked_to || []).map(l => l.id)
                };
            }
        }

        // If no match on this page, check if there are more pages
        if (items.length === perPage && page < 10) {
            page++;
            return findMostRecent();
        }

        return null; // No match found in the history
    });
}

