const headers = {
  'ACCESS_TOKEN': apiToken,
  'Content-Type': 'application/json'
};

try {
  // 1. Fetch Opportunities
  const oppResponse = await fetch('https://api.crmworkspace.com/v1/opportunities', { headers });
  if (!oppResponse.ok) throw new Error(`Opp Fetch Error: ${oppResponse.status}`);

  const oppData = await oppResponse.json();
  const opportunities = oppData.opportunities || [];

  // Finding the match (cleaning "Household" as requested)
  const match = opportunities.find(opp => 
    opp.name.toLowerCase().trim() === targetName.replace("Household","").toLowerCase().trim()
  );

  if (!match) {
    return { found: false, message: "No matching opportunity found." };
  }

  // 2. Fetch All Workflow Stages
  const stageResponse = await fetch('https://api.crmworkspace.com/v1/categories/opportunity_stages', { headers });
  if (!stageResponse.ok) throw new Error(`Stage Fetch Error: ${stageResponse.status}`);

  const stageData = await stageResponse.json();
  const allStages = stageData.opportunity_stages || [];

  // 3. Find the name of the current stage based on the ID in the match
  // Note: Depending on your Wealthbox version, match.stage might be an ID or a String.
  // We'll search the allStages array for a match.
  const currentStageObj = allStages.find(s => s.id === match.stage || s.name === match.stage);

  return {
    found: true,
    opportunity_id: match.id,
    opportunity_name: match.name,
    current_stage_name: currentStageObj ? currentStageObj.name : match.stage.name,
    current_stage_id: match.stage ? currentStageObj.id : null,
    // Returns all stages as a comma-separated list or JSON string for Zapier mapping
    all_stage_names: allStages.map(s => s.name).join(', '),
    all_stage_ids: allStages.map(s => s.id).join(', '),
    // Optional: Return raw array for nested use in later steps
    stages_raw: allStages 
  };

} catch (error) {
  return { error: error.message };
}
